/**
 * ModelEditModal.tsx — 管理页 · 模型配置编辑弹窗（Manager/Worker 详情面板共用）。
 *
 * 任务 A（模型弹窗化 + 响应式）：
 * - 宽屏（≥640px）：模型 / Provider 左右排列（flex gap 12，各约 50%）；
 * - 窄屏（<640px）：上下排列（grid gap 14，全宽）；
 * - 弹窗宽 Math.min(560, innerWidth - 48)；字段标题字号 宽 14px / 窄 12px。
 *
 * 两面板共用本组件保证零分叉：候选 options / alias→provider 自动回填 /
 * 当前值摘要同源（modelUnion）；草稿态由本组件持有（打开时按当前值重置）；
 * onSave 返回 true = 保存成功（父级关弹窗），false = 校验或写失败（停留）。
 */
import type * as ReactNS from "react";

import { useThemeColors } from "../theme";
import { useT } from "../i18n";
import { providerForModel, useModelUnionOptions } from "../modelUnion";

const host = window.QwenPaw.host;
const React: typeof ReactNS = host.React;
const antd = host.antd;

/** useModelUnionOptions 返回态（接口未导出——用 ReturnType 精确引用）。 */
type UnionState = ReturnType<typeof useModelUnionOptions>;

export default function ModelEditModal({
  open,
  title,
  currentModel,
  currentProvider,
  union,
  saving,
  onCancel,
  onSave,
}: {
  open: boolean;
  title: string;
  /** 当前已保存模型（dirty 比较基线）。 */
  currentModel: string;
  /** 当前已保存 provider（基线含 alias binding 回退推导）。 */
  currentProvider: string;
  /** 候选并集（父面板提供——与各入口同源，避免重复拉取）。 */
  union: UnionState;
  /** 保存中（父级 PUT 在途）→ OK 按钮 loading。 */
  saving: boolean;
  onCancel: () => void;
  /** 保存（父级做校验 + PUT + message）；true=成功关闭，false=停留。 */
  onSave: (model: string, provider: string) => Promise<boolean>;
}) {
  const t = useThemeColors();
  const tr = useT();
  const [model, setModel] = React.useState("");
  const [provider, setProvider] = React.useState("");

  // 打开时重置草稿（以打开瞬间的当前值为基线）。
  React.useEffect(() => {
    if (open) {
      setModel(currentModel);
      setProvider(currentProvider);
    }
  }, [open, currentModel, currentProvider]);
  // 打开时刷新 SGLang 在服列表（union.refetchSglang 注释语义）。
  React.useEffect(() => {
    if (open) union.refetchSglang();
    // 仅按 open 触发——union 每 render 新对象，进 deps 会循环重置草稿。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const isNarrow = typeof window !== "undefined" && window.innerWidth < 640;
  const fieldsLayout = isNarrow
    ? ({ display: "grid", gap: 14 } as const)
    : ({ display: "flex", gap: 12 } as const);
  const fieldStyle = isNarrow
    ? ({ width: "100%" } as const)
    : ({ flex: 1, minWidth: 0 } as const);
  const labelStyle = {
    fontSize: isNarrow ? 12 : 14,
    color: t.textSecondary,
    marginBottom: 6,
  };

  const dirty = model !== currentModel || provider !== currentProvider;

  const handleOk = async () => {
    // 受控 open：成功时父级置 open=false 关闭；失败停留保留草稿。
    await onSave(model, provider);
  };

  return (
    <antd.Modal
      title={title}
      open={open}
      onCancel={onCancel}
      onOk={handleOk}
      okText={tr("保存")}
      cancelText={tr("取消")}
      confirmLoading={saving}
      okButtonProps={{ disabled: !dirty }}
      width={Math.min(560, window.innerWidth - 48)}
      destroyOnClose
    >
      <div style={{ display: "grid", gap: 14, padding: "8px 0" }}>
        <div style={fieldsLayout}>
          <div style={fieldStyle}>
            <div style={labelStyle}>{tr("模型")}</div>
            <antd.Select
              style={{ width: "100%" }}
              size="large"
              showSearch
              allowClear
              placeholder={tr("模型 alias（留空=跟随集群默认）")}
              value={model || undefined}
              onChange={(v: string) => {
                setModel(v ?? "");
                // configured alias → 自动回填其 binding.providerName。
                const auto = providerForModel(union.gatewayOptions, v ?? "");
                if (auto) setProvider(auto);
              }}
              options={union.options as any[]}
              filterOption={(input: string, option: any) =>
                String(option?.label ?? option?.value ?? "")
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
            />
          </div>
          <div style={fieldStyle}>
            <div style={labelStyle}>{tr("Provider")}</div>
            <antd.Select
              style={{ width: "100%" }}
              size="large"
              showSearch
              allowClear
              placeholder={tr("自动（跟随默认）")}
              value={provider || undefined}
              onChange={(v: string) => setProvider(v ?? "")}
              options={union.providers.map((p) => ({
                value: p.name,
                label: p.name,
              }))}
            />
          </div>
        </div>
        {/* 当前值摘要（只读）。 */}
        <div
          style={{
            fontSize: 11,
            color: t.textSecondary,
            padding: "6px 10px",
            borderRadius: 4,
            background: t.cardBg,
          }}
        >
          {tr("当前")}：{currentModel || "-"}
          {currentProvider ? ` · ${currentProvider}` : ""}
        </div>
      </div>
    </antd.Modal>
  );
}
